export const getElementId = (elementId?: string, groupId?: string) => {
    if (elementId && groupId) {
        return `item-${elementId}-${groupId}`;
    }

    if (elementId) {
        return `item-${elementId}`;
    }

    if (groupId) {
        return `group-${groupId}`;
    }

    return undefined;
};
